select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_TARE_PLANNING','RRL_STOCK_TARE_BOOK_CMD','RRL_STOCK_TARE_CMD','RRL_STOCK_TARE_RESOLVE','RRL_STOCK_POSTING_API','RRL_TARE_AVAILABILITY','RRL_TARE_BOOK_GUARD','RRL_CASE_TARE_START_GUARD','RRL_HU_TARE_LINK_GUARD','RRL_HU_TARE_WARE_GUARD') order by OBJECT_NAME,OBJECT_TYPE;
select count(*) NEGATIVE_AVAILABLE from RRL_TARE_AVAILABILITY where AVAILABLE_QTY<0;
select MIGRATION_ID,STATUS from RRL_SCHEMA_MIGRATIONS where MIGRATION_ID='2026-10-10-101-tare-existing-assembly';
